function cellX(g){return leftM+(g-1)*step;}
function cellY(p){return topM+(p-1)*step;}
function getColor(ck){
  var map={purple:colPurple,green:colGreen,tan:colTan,pink:colPink,lavender:colLavender,cyan:colCyan,white:colWhite,gray:colGray};
  return map[ck]||colWhite;
}

// Charge-based coloring
function chargeColor(el){
  if(el.ch.length===0) return '#d0d0d0';
  var c=el.ch[0];
  var val=0;
  if(c.indexOf('⁺')>-1){
    var m=c.match(/([²³⁴⁵⁶⁷⁸⁹]*)⁺/);
    var sup=m?m[1]:'';
    var numMap={'²':2,'³':3,'⁴':4,'⁵':5,'⁶':6,'⁷':7,'⁸':8,'⁹':9};
    val=numMap[sup]||1;
    if(c.indexOf('₂')>-1) val=1; // Hg2 2+ is +1 per atom
  } else if(c.indexOf('⁻')>-1){
    var m2=c.match(/([²³⁴])⁻/);
    var sup2=m2?m2[1]:'';
    var numMap2={'²':2,'³':3,'⁴':4};
    val=-(numMap2[sup2]||1);
  }
  if(el.ch.length>1) return '#f0c060'; // variable = gold
  if(val>=3) return '#e05030';
  if(val===2) return '#f08040';
  if(val===1) return '#f8c870';
  if(val===-1) return '#70b8f0';
  if(val===-2) return '#4080d0';
  if(val===-3) return '#3050a0';
  if(val===-4) return '#203080';
  return '#d0d0d0';
}

