function drawCells(){
  // Clear old
  cellRects.forEach(function(r){r.remove();});
  cellTexts.forEach(function(t){t.remove();});
  cellRects=[];cellTexts=[];
  if(highlightRect){highlightRect.remove();highlightRect=null;}
  if(infoGroup){infoGroup.remove();infoGroup=null;}

  elements.forEach(function(el,idx){
    var x=cellX(el.g),y=cellY(el.p);
    var fill=useChargeColor?chargeColor(el):getColor(el.ck);
    var rect=draw.rect(cellW,cellH).attr({x:x,y:y,fill:fill,stroke:'#999','stroke-width':0.5}).css('cursor','pointer');
    rect.on('click',function(){selectElement(el);});
    rect.on('mousemove',function(e){showTooltip(el.s+(el.ch.length?' → '+el.ch.join(', '):' (no common ion)'),e);});
    rect.on('mouseleave',function(){hideTooltip();});
    cellRects.push(rect);

    // Charge text
    if(el.ch.length===1){
      var t=draw.text(el.ch[0]).font({size:10,weight:'bold',fill:'#000'}).attr({x:x+cellW/2,y:y+cellH/2+3,'text-anchor':'middle'});
      t.css('pointer-events','none');
      cellTexts.push(t);
    } else if(el.ch.length===2){
      var t1=draw.text(el.ch[0]).font({size:9,weight:'bold',fill:'#000'}).attr({x:x+cellW/2,y:y+cellH/2-4,'text-anchor':'middle'});
      var t2=draw.text(el.ch[1]).font({size:9,weight:'bold',fill:'#000'}).attr({x:x+cellW/2,y:y+cellH/2+8,'text-anchor':'middle'});
      t1.css('pointer-events','none');t2.css('pointer-events','none');
      cellTexts.push(t1,t2);
    }
  });

  // F-block rows
  var fStartX=leftM+2*step;
  for(var i=0;i<14;i++){
    var fx=fStartX+i*step;
    var fy1=fBlockTop;
    var fy2=fBlockTop+step;
    var r1=draw.rect(cellW,cellH).attr({x:fx,y:fy1,fill:useChargeColor?'#d0d0d0':colGreen,stroke:'#999','stroke-width':0.5});
    var r2=draw.rect(cellW,cellH).attr({x:fx,y:fy2,fill:useChargeColor?'#d0d0d0':colPink,stroke:'#999','stroke-width':0.5});
    cellRects.push(r1,r2);
  }
  // Labels * and **
  draw.text('*').font({size:10,fill:'#000'}).attr({x:fStartX-12,y:fBlockTop+cellH/2+3});
  draw.text('**').font({size:10,fill:'#000'}).attr({x:fStartX-16,y:fBlockTop+step+cellH/2+3});

  // Red outline around group 3, periods 6-7
  var rx=cellX(3)-1,ry=cellY(6)-1;
  var rw=cellW+2,rh=2*step+2;
  draw.rect(rw,rh).attr({x:rx,y:ry,fill:'none',stroke:'#cc0000','stroke-width':2});

  // Curved arrow from red box to f-block
  var arrowStartX=cellX(3)+cellW/2;
  var arrowStartY=cellY(7)+cellH;
  var arrowEndX=fStartX-20;
  var arrowEndY=fBlockTop+step/2;
  var path=draw.path('M '+arrowStartX+' '+arrowStartY+' C '+arrowStartX+' '+(arrowStartY+30)+' '+arrowEndX+' '+(arrowEndY-20)+' '+arrowEndX+' '+arrowEndY);
  path.fill('none').stroke({color:'#cc0000',width:2});
  // Arrowhead
  draw.polygon((arrowEndX-5)+','+(arrowEndY-8)+' '+(arrowEndX+5)+','+(arrowEndY-8)+' '+arrowEndX+','+(arrowEndY+2)).fill('#cc0000');

  // Highlight column
  if(highlightGroup>=1&&highlightGroup<=18){
    var hx=cellX(highlightGroup)-1;
    var hy=topM-1;
    var hh=7*step+2;
    highlightRect=draw.rect(cellW+2,hh).attr({x:hx,y:hy,fill:'none',stroke:'#ff6600','stroke-width':2.5,'stroke-dasharray':'6,3',rx:3});
  }

  // Info card for selected element
  if(selectedEl){
    drawInfoCard(selectedEl);
  }
}

function drawInfoCard(el){
  infoGroup=draw.group();
  var cx=cellX(el.g)+cellW/2;
  var cy=cellY(el.p)+cellH/2;
  // Position card to the right or left
  var cardW=180,cardH=70;
  var cardX=cx+cellW/2+8;
  var cardY=cy-cardH/2;
  if(cardX+cardW>W-10) cardX=cx-cellW/2-cardW-8;
  if(cardY<10) cardY=10;
  if(cardY+cardH>H-10) cardY=H-cardH-10;

  infoGroup.rect(cardW,cardH).attr({x:cardX,y:cardY,fill:'#fffef0',stroke:'#333','stroke-width':1.5,rx:4});
  var line1=el.s+(el.ch.length?'  →  '+el.ch.join(' / '):'  (no common ion)');
  infoGroup.text(line1).font({size:10,weight:'bold',fill:'#000'}).attr({x:cardX+8,y:cardY+14});
  infoGroup.text('Config: '+el.cfg).font({size:9,fill:'#333'}).attr({x:cardX+8,y:cardY+30});
  // Wrap rule text
  var ruleText=el.rule;
  var words=ruleText.split(' ');
  var lines=[];var cur='';
  words.forEach(function(w){
    if((cur+' '+w).length>38){lines.push(cur);cur=w;}
    else cur=cur?cur+' '+w:w;
  });
  if(cur)lines.push(cur);
  lines.slice(0,3).forEach(function(l,i){
    infoGroup.text(l).font({size:8,fill:'#555'}).attr({x:cardX+8,y:cardY+44+i*11});
  });

  // Bold ring on selected cell
  var sx=cellX(el.g)-2,sy=cellY(el.p)-2;
  infoGroup.rect(cellW+4,cellH+4).attr({x:sx,y:sy,fill:'none',stroke:'#ff0000','stroke-width':3,rx:2});
}

function selectElement(el){
  selectedEl=el;
  drawCells();
}

drawCells();

// Interactions
window.update_groupSweep=function(v){
  highlightGroup=v;
