{s:'Ts',g:17,p:7,ch:[],ck:'white',cfg:'[Rn]5f¹⁴6d¹⁰7s²7p⁵',rule:'Group 17: predicted −1.'},
{s:'Og',g:18,p:7,ch:[],ck:'white',cfg:'[Rn]5f¹⁴6d¹⁰7s²7p⁶',rule:'Noble gas: predicted stable.'}
];

// F-block rows
var lanthanides=['La','Ce','Pr','Nd','Pm','Sm','Eu','Gd','Tb','Dy','Ho','Er','Tm','Yb'];
var actinides=['Ac','Th','Pa','U','Np','Pu','Am','Cm','Bk','Cf','Es','Fm','Md','No'];

function cellX(g){return leftM+(g-1)*step;}
function cellY(p){return topM+(p-1)*step;}
function getColor(ck){
  var map={purple:colPurple,green:colGreen,tan:colTan,pink:colPink,lavender:colLavender,cyan:colCyan,white:colWhite,gray:colGray};
  return map[ck]||colWhite;
}

// Charge-based coloring
function chargeColor(el){
  if(el.ch.length===0) return '#d0d0d0';
  var c=el.ch[0];
  var val=0;
  if(c.indexOf('⁺')>-1){
    var m=c.match(/([²³⁴⁵⁶⁷⁸⁹]*)⁺/);
    var sup=m?m[1]:'';
    var numMap={'²':2,'³':3,'⁴':4,'⁵':5,'⁶':6,'⁷':7,'⁸':8,'⁹':9};
    val=numMap[sup]||1;
    if(c.indexOf('₂')>-1) val=1; // Hg2 2+ is +1 per atom
  } else if(c.indexOf('⁻')>-1){
    var m2=c.match(/([²³⁴])⁻/);
    var sup2=m2?m2[1]:'';
    var numMap2={'²':2,'³':3,'⁴':4};
    val=-(numMap2[sup2]||1);
  }
  if(el.ch.length>1) return '#f0c060'; // variable = gold
  if(val>=3) return '#e05030';
  if(val===2) return '#f08040';
  if(val===1) return '#f8c870';
  if(val===-1) return '#70b8f0';
  if(val===-2) return '#4080d0';
  if(val===-3) return '#3050a0';
  if(val===-4) return '#203080';
  return '#d0d0d0';
}

var useChargeColor=false;
var highlightGroup=1;
var selectedEl=null;

// Draw group labels
for(var g=1;g<=18;g++){
  draw.text(String(g)).font({size:11,weight:'bold',fill:'#0000cc'}).attr({x:cellX(g)+cellW/2,y:topM-14,'text-anchor':'middle'});
}
// Period labels
for(var p=1;p<=7;p++){
  draw.text(String(p)).font({size:11,weight:'bold',fill:'#8800aa'}).attr({x:leftM-14,y:cellY(p)+cellH/2+4,'text-anchor':'middle'});
}
// Axis labels
draw.text('Group').font({size:11,weight:'bold',fill:'#0000cc'}).attr({x:leftM+4*step,y:topM-26,'text-anchor':'middle'});
draw.text('Period').font({size:11,weight:'bold',fill:'#8800aa'}).attr({x:8,y:topM+3*step,'text-anchor':'middle',transform:'rotate(-90 8 '+(topM+3*step)+')'});

// Title
draw.text('Periodic Table of the Elements').font({size:14,weight:'bold',fill:'#000'}).attr({x:W/2,y:12,'text-anchor':'middle'});

// Cell groups for redrawing
var cellRects=[];
var cellTexts=[];
var highlightRect=null;
var infoGroup=null;

function drawCells(){
  // Clear old
  cellRects.forEach(function(r){r.remove();});
  cellTexts.forEach(function(t){t.remove();});
  cellRects=[];cellTexts=[];
  if(highlightRect){highlightRect.remove();highlightRect=null;}
  if(infoGroup){infoGroup.remove();infoGroup=null;}

  elements.forEach(function(el,idx){
    var x=cellX(el.g),y=cellY(el.p);
    var fill=useChargeColor?chargeColor(el):getColor(el.ck);
    var rect=draw.rect(cellW,cellH).attr({x:x,y:y,fill:fill,stroke:'#999','stroke-width':0.5}).css('cursor','pointer');
    rect.on('click',function(){selectElement(el);});
    rect.on('mousemove',function(e){showTooltip(el.s+(el.ch.length?' → '+el.ch.join(', '):' (no common ion)'),e);});
    rect.on('mouseleave',function(){hideTooltip();});
    cellRects.push(rect);

    // Charge text
    if(el.ch.length===1){
      var t=draw.text(el.ch[0]).font({size:10,weight:'bold',fill:'#000'}).attr({x:x+cellW/2,y:y+cellH/2+3,'text-anchor':'middle'});
      t.css('pointer-events','none');
      cellTexts.push(t);
    } else if(el.ch.length===2){
      var t1=draw.text(el.ch[0]).font({size:9,weight:'bold',fill:'#000'}).attr({x:x+cellW/2,y:y+cellH/2-4,'text-anchor':'middle'});
      var t2=draw.text(el.ch[1]).font({size:9,weight:'bold',fill:'#000'}).attr({x:x+cellW/2,y:y+cellH/2+8,'text-anchor':'middle'});
      t1.css('pointer-events','none');t2.css('pointer-events','none');
      cellTexts.push(t1,t2);
    }
  });

  // F-block rows
  var fStartX=leftM+2*step;
  for(var i=0;i<14;i++){
    var fx=fStartX+i*step;
    var fy1=fBlockTop;
    var fy2=fBlockTop+step;
    var r1=draw.rect(cellW,cellH).attr({x:fx,y:fy1,fill:useChargeColor?'#d0d0d0':colGreen,stroke:'#999','stroke-width':0.5});
    var r2=draw.rect(cellW,cellH).attr({x:fx,y:fy2,fill:useChargeColor?'#d0d0d0':colPink,stroke:'#999','stroke-width':0.5});
    cellRects.push(r1,r2);
  }
  // Labels * and **
  draw.text('*').font({size:10,fill:'#000'}).attr({x:fStartX-12,y:fBlockTop+cellH/2+3});
  draw.text('**').font({size:10,fill:'#000'}).attr({x:fStartX-16,y:fBlockTop+step+cellH/2+3});

  // Red outline around group 3, periods 6-7
  var rx=cellX(3)-1,ry=cellY(6)-1;
  var rw=cellW+2,rh=2*step+2;
  draw.rect(rw,rh).attr({x:rx,y:ry,fill:'none',stroke:'#cc0000','stroke-width':2});

  // Curved arrow from red box to f-block
  var arrowStartX=cellX(3)+cellW/2;
  var arrowStartY=cellY(7)+cellH;
  var arrowEndX=fStartX-20;
  var arrowEndY=fBlockTop+step/2;
  var path=draw.path('M '+arrowStartX+' '+arrowStartY+' C '+arrowStartX+' '+(arrowStartY+30)+' '+arrowEndX+' '+(arrowEndY-20)+' '+arrowEndX+' '+arrowEndY);
  path.fill('none').stroke({color:'#cc0000',width:2});
  // Arrowhead
  draw.polygon((arrowEndX-5)+','+(arrowEndY-8)+' '+(arrowEndX+5)+','+(arrowEndY-8)+' '+arrowEndX+','+(arrowEndY+2)).fill('#cc0000');

  // Highlight column
  if(highlightGroup>=1&&highlightGroup<=18){
    var hx=cellX(highlightGroup)-1;
    var hy=topM-1;
    var hh=7*step+2;
    highlightRect=draw.rect(cellW+2,hh).attr({x:hx,y:hy,fill:'none',stroke:'#ff6600','stroke-width':2.5,'stroke-dasharray':'6,3',rx:3});
  }

  // Info card for selected element
  if(selectedEl){
    drawInfoCard(selectedEl);
  }
}

function drawInfoCard(el){
  infoGroup=draw.group();
  var cx=cellX(el.g)+cellW/2;
  var cy=cellY(el.p)+cellH/2;
  // Position card to the right or left
  var cardW=180,cardH=70;
  var cardX=cx+cellW/2+8;
  var cardY=cy-cardH/2;
  if(cardX+cardW>W-10) cardX=cx-cellW/2-cardW-8;
  if(cardY<10) cardY=10;
  if(cardY+cardH>H-10) cardY=H-cardH-10;

  infoGroup.rect(cardW,cardH).attr({x:cardX,y:cardY,fill:'#fffef0',stroke:'#333','stroke-width':1.5,rx:4});
  var line1=el.s+(el.ch.length?'  →  '+el.ch.join(' / '):'  (no common ion)');
  infoGroup.text(line1).font({size:10,weight:'bold',fill:'#000'}).attr({x:cardX+8,y:cardY+14});
  infoGroup.text('Config: '+el.cfg).font({size:9,fill:'#333'}).attr({x:cardX+8,y:cardY+30});
  // Wrap rule text
  var ruleText=el.rule;
  var words=ruleText.split(' ');
  var lines=[];var cur='';
  words.forEach(function(w){
    if((cur+' '+w).length>38){lines.push(cur);cur=w;}
    else cur=cur?cur+' '+w:w;
  });
  if(cur)lines.push(cur);
  lines.slice(0,3).forEach(function(l,i){
    infoGroup.text(l).font({size:8,fill:'#555'}).attr({x:cardX+8,y:cardY+44+i*11});
  });

  // Bold ring on selected cell
  var sx=cellX(el.g)-2,sy=cellY(el.p)-2;
  infoGroup.rect(cellW+4,cellH+4).attr({x:sx,y:sy,fill:'none',stroke:'#ff0000','stroke-width':3,rx:2});
}

function selectElement(el){
  selectedEl=el;
  drawCells();
}

drawCells();

// Interactions
window.update_groupSweep=function(v){
  highlightGroup=v;
  drawCells();
};

window.toggle_colorScheme=function(on){
  useChargeColor=on;
  drawCells();
};

// Demo steps
var steps=[
  {title:'Cations on the left',narration:'With element-type coloring and the slider on group 1, the highlighted column shows every alkali metal as a +1 cation; group 2 is +2. The positive charge simply equals the group number because these metals lose their outer electrons.',state:{groupSweep:1,colorScheme:false}},
  {title:'Anions on the right',narration:'Sweep the slider to group 17: the halogens are all −1, group 16 is −2, group 15 is −3. The negative charge equals 18 minus the group number — the electrons needed to complete the noble-gas shell.',state:{groupSweep:17,colorScheme:false}},
  {title:'Transition metals break the rule',narration:'Move the slider into the d-block (e.g. group 8) and click iron: it shows Fe²⁺ AND Fe³⁺, with no single group-number rule. Click chromium or copper to see the same variability — position alone cannot predict transition-metal charge.',state:{groupSweep:8,colorScheme:false}},
  {title:'Two ways to see the same pattern',narration:'Toggle to ion-charge coloring: the table recolors by charge magnitude, turning the metal-to-nonmetal transition into a smooth visual gradient and making the noble-gas column (charge 0) read as the neutral pivot of the whole trend.',state:{groupSweep:1,colorScheme:true}}
];
var curStep=0;

function applyStep(i){
  curStep=i;
  var st=steps[i].state;
  highlightGroup=st.groupSweep;
  useChargeColor=st.colorScheme;
  document.getElementById('groupSweepInput').value=st.groupSweep;
  document.getElementById('groupSweepVal').value=st.groupSweep;
  document.getElementById('colorSchemeInput').checked=st.colorScheme;
  document.getElementById('demoNarration').textContent=steps[i].narration;
  document.getElementById('stepLabel').textContent=(i+1)+'/'+steps.length;
  selectedEl=null;
  drawCells();
}

window.nextStep=function(){applyStep(Math.min(curStep+1,steps.length-1));};
window.prevStep=function(){applyStep(Math.max(curStep-1,0));};

applyStep(0);
window.__markRendered();
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: An element's group position reliably predicts its common ionic charge for main-group elements (cations equal to the group number, anions equal to the steps left of the noble gases), but transition metals break this rule by forming several variable charges.
KEY INSIGHT (what students should walk away understanding): For main-group elements the common ionic charge is read straight off the group number (lose that many electrons, or gain up to the noble-gas configuration), but transition metals form multiple variable charges that no group-position rule can predict.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "An element's group position reliably predicts its common ionic charge for main-group elements (cations equal to the group number, anions equal to the steps left of the noble gases), but transition metals break this rule by forming several variable charges.",
  "figureType": "diagram",
  "elements": [
    "title 'Periodic Table of the Elements' centered at top",
    "group-number labels 1 through 18 in blue across the top edge",
    "period-number labels 1 through 7 in purple down the left edge",
