];
var curStep=0;

function applyStep(i){
  curStep=i;
  var st=steps[i].state;
  highlightGroup=st.groupSweep;
  useChargeColor=st.colorScheme;
  document.getElementById('groupSweepInput').value=st.groupSweep;
  document.getElementById('groupSweepVal').value=st.groupSweep;
  document.getElementById('colorSchemeInput').checked=st.colorScheme;
  document.getElementById('demoNarration').textContent=steps[i].narration;
  document.getElementById('stepLabel').textContent=(i+1)+'/'+steps.length;
  selectedEl=null;
  drawCells();
}

window.nextStep=function(){applyStep(Math.min(curStep+1,steps.length-1));};
window.prevStep=function(){applyStep(Math.max(curStep-1,0));};

applyStep(0);
window.__markRendered();
